 return `<div class="fac-detail"><div class="fac-detail-head"><span class="fac-detail-icon">${rrFacilityIcon(name)}</span><div><strong>${name}</strong><span class="fac-status${st.open?' open':''}">${st.text}</span></div></div>${ck?`<p class="fac-note" data-rr-fr="${ck[1]}">${ck[0]}</p><p class="fac-note fac-checkin-limit" data-rr-fr="${RR_CHECKIN_LIMIT[1]}">${RR_CHECKIN_LIMIT[0]}</p>`:RR_FAC_NOTE[name]?`<p class="fac-note">${RR_FAC_NOTE[name]}</p>`:''}<dl class="fac-hours">${rrHoursRows(hours).map(([d,t])=>`<div><dt>${d}</dt><dd>${t}</dd></div>`).join('')}</dl></div>`;
