  const text=se('text',{x:textX,y:chosen.y+fontSize,'text-anchor':chosen.anchor,style:`font-size:${fontSize}px`,class:'label'+(important?' important':'')+(chosen.overLines?' over-lines':''),'pointer-events':'all'});
